import type {Shot,Storyboard,Narration} from '../core/schemas.js';
import type {Gesture} from '../animation/schemas.js';
import type {CinematicPlan} from './schemas.js';
import {rigHand} from '../core/identifiers.js';
import {hash} from '../core/utils.js';
import {isWholeSourceStatement} from '../explainer/plan.js';
import {actorProfile} from '../actors/model.js';
import {actorViewActingClock} from '../actors/view-acting-clock.js';
import {samplePhysicalPerformance} from '../animation/compiler.js';
import {performanceProps} from '../animation/view-source-manipulation.js';
import {hasBodyViewManipulation} from '../animation/native-contact-arm.js';
import {validateManipulationActionSlices} from './source-manipulation-actions.js';
import {boundProp,propPerformer,assertPropAliasCoverage} from './prop-owner.js';
import {SOURCE_PROP_BINDING_VERSION} from './source-prop-identity.js';
import {partAnchor} from '../host/controller.js';
import {validateSourceGripWorld} from './source-grip-world.js';

type Binding=CinematicPlan['propBindings'][number];
const fail=(shot:Shot,message:string):never=>{throw new Error(`${shot.id}: needs-source-prop-binding: ${message}`);};
export function originalPropGesture(shot:Shot,binding:Binding){
  const owner=boundProp(shot,binding),gestures=owner.performance.sourceManipulation?.gestures??owner.performance.gestures;
  const matches=gestures.filter(g=>g.propId===binding.propId&&g.action!=='operate');
  if(matches.length!==1)return fail(shot,`model ${binding.partId} needs exactly one original attachment`);
  return {...owner,gesture:matches[0]!};
}
/** Real original geometry at a shot-local boundary. No audio, destination
 * shortcut, guessed palm, local contact reset or physical history mutation. */
export function sourceBoundPropFrame(shot:Shot,binding:Binding,timeMs:number,board:Storyboard|undefined){
  const owner=boundProp(shot,binding);
  if(!owner.performance.sourceManipulation||!owner.character||binding.ownerId!==owner.id||!board)
    return fail(shot,'original model geometry needs the explicit story owner and complete storyboard');
  const clock=actorViewActingClock(board,shot,owner.id);
  if(!clock?.manipulationMotion)return fail(shot,'missing complete original contact/body/head clock');
  const frame=samplePhysicalPerformance(owner.performance,actorProfile(owner.character),timeMs,clock),state=frame.props[binding.propId];
  if(!state)return fail(shot,'original model has no physical state');
  return {owner,clock,frame,state};
}
function descriptor(shot:Shot,binding:Binding){
  const owner=originalPropGesture(shot,binding),part=shot.visualization?.parts.find(p=>p.id===binding.partId),model=shot.cinematic?.models.find(m=>m.partId===binding.partId),art=shot.cinematic?.artDirection?.models.find(m=>m.partId===binding.partId);
  if(!part||!model)return fail(shot,'missing original model/entity descriptor');
  return {owner,part,model,art,identity:{ownerId:owner.id,propId:binding.propId,part,model,art:art??null,role:binding.role,sourceRefs:binding.sourceRefs}};
}
function citedContact(shot:Shot,ownerId:string,gesture:Gesture,partId:string,narration:Narration,startMs:number){
  const operation=gesture.action==='operate'?'contact':gesture.action;
  const evidence=shot.cinematic?.sceneIntent?.acting?.filter(a=>a.participantId===ownerId&&a.kind==='manipulation'&&a.operation===operation&&a.targetIds?.includes(partId))??[];
  const witnesses=evidence.flatMap(expected=>expected.sourceRefs.flatMap(ref=>{
    if(ref.kind!=='narration'||!isWholeSourceStatement(expected.statement,ref.quote))return [];
    const cue=narration.segments.find(s=>s.id===ref.segmentId&&s.text.normalize('NFC').includes(ref.quote.normalize('NFC')));
    if(!cue||!isWholeSourceStatement(expected.statement,cue.text)||startMs+gesture.contactMs!<cue.startMs||startMs+gesture.contactMs!>=cue.endMs)return [];
    if(gesture.releaseMs!==undefined&&startMs+gesture.releaseMs>cue.endMs||gesture.landingMs!==undefined&&startMs+gesture.landingMs>cue.endMs)return [];
    return [{cueId:cue.id,sourceRef:ref,statement:expected.statement}];
  }));
  return witnesses;
}
/** Validate the real complete original actor/model history, including every
 * camera slice and primary/supporting swap. Does not approve artwork or open
 * the still-pending world/event/effect renderer contract. */
export function validateSourcePropBindings(shot:Shot,board:Storyboard|undefined,narration:Narration|undefined):void{
  const c=shot.cinematic;if(!c)return;
  const sourceOwners=[...(c.actorScene?.primary&&c.performance.sourceManipulation?[{id:c.actorScene.primary.id,performance:c.performance}]:[]),
    ...(c.actorScene?.supporting.filter(a=>a.performance.sourceManipulation).map(a=>({id:a.character.id,performance:a.performance}))??[])];
  if(!sourceOwners.length){if(c.performance.sourceManipulation)return fail(shot,'original contact requires a visible sourced story actor');return;}
  if(!board||!narration)return fail(shot,'complete storyboard and original narration are required for model evidence');
  if(board.shots.filter(s=>s.id===shot.id).length!==1||hash(board.shots.find(s=>s.id===shot.id))!==hash(shot))return fail(shot,'candidate differs from its authoritative complete storyboard');
  for(const sourceOwner of sourceOwners){
    const source=sourceOwner.performance.sourceManipulation!,clock=actorViewActingClock(board,shot,sourceOwner.id);
    if(!clock?.manipulationMotion)return fail(shot,'missing complete original actor contact clock');
    const slices=board.shots.filter(s=>s.startMs>=source.startMs&&s.endMs<=source.endMs).sort((a,b)=>a.startMs-b.startMs);
    let end=source.startMs;
    for(const slice of slices){if(slice.startMs!==end)return fail(shot,'model source camera coverage has a gap');end=slice.endMs;}
    if(end!==source.endMs)return fail(shot,'model source camera coverage is incomplete');
    for(const slice of slices){
      assertPropAliasCoverage(slice);
      const bindings=slice.cinematic!.propBindings;
      if(new Set(bindings.map(b=>b.partId)).size!==bindings.length)return fail(slice,'ambiguous visible prop/model/painter ownership');
    }
    for(const prop of performanceProps(sourceOwner.performance)){
      const current=c.propBindings.filter(b=>b.propId===prop.id&&b.ownerId===sourceOwner.id);
      if(current.length!==1)return fail(shot,'each original prop needs exactly one explicit person/model binding');
      const canonical=descriptor(shot,current[0]!),p=canonical.owner.performance,offset=prop.gripOffset??{x:0,y:0};
      if(canonical.owner.id!==sourceOwner.id||!canonical.owner.character)return fail(shot,'original model person is not visible');
      if(!hasBodyViewManipulation(actorProfile(canonical.owner.character)))return fail(shot,'original model requires explicit own native manipulation selection');
      if(Math.abs(prop.origin.x-canonical.part.x*p.stage.width)>Number.EPSILON*4*Math.max(1,p.stage.width)||Math.abs(prop.origin.y-canonical.part.y*p.stage.height)>Number.EPSILON*4*Math.max(1,p.stage.height))return fail(shot,'model canonical origin differs from the original prop center');
      if(Math.hypot(canonical.owner.gesture.target!.x-prop.origin.x-offset.x*p.scale,canonical.owner.gesture.target!.y-prop.origin.y-offset.y*p.scale)>1e-6)return fail(shot,'original grip target differs from its actual model center/offset');
      if(canonical.owner.gesture.destination&&(!prop.destination||Math.hypot(canonical.owner.gesture.destination.x-offset.x*p.scale-prop.destination.x,canonical.owner.gesture.destination.y-offset.y*p.scale-prop.destination.y)>1e-6))return fail(shot,'original placed center differs from the original grip destination');
      for(const slice of slices){
        const matches=slice.cinematic?.propBindings.filter(b=>b.propId===prop.id&&b.ownerId===sourceOwner.id)??[];
        if(matches.length!==1)return fail(slice,'original model binding missing, duplicated or assigned to another person');
        const binding=matches[0]!,next=descriptor(slice,binding),owned=next.owner;
        if(hash(owned.performance.stage)!==hash(slice.cinematic!.performance.stage)||owned.performance.durationMs!==slice.endMs-slice.startMs||owned.performance.leadCharacterId!==owned.id)return fail(slice,'original model has a different scene stage/clock/person');
        if(hash(next.identity)!==hash(canonical.identity))return fail(slice,'original entity/model/art/source/size/origin identity changed at a cut');
        if(!owned.performance.sourceManipulation||hash(owned.performance.sourceManipulation)!==hash(source)||owned.id!==sourceOwner.id)return fail(slice,'original contact source/person changed at a cut');
        if(!slice.cinematic?.artDirection||!['authored','model'].includes(slice.cinematic.artDirection.origin))return fail(slice,'original model requires sourced authored/model direction');
        if(!binding.sourceRefs.length||binding.sourceRefs.some(ref=>!next.part.sourceRefs.some(r=>hash(r)===hash(ref)))||next.art&&binding.sourceRefs.some(ref=>!next.art!.sourceRefs.some(r=>hash(r)===hash(ref))))return fail(slice,'original binding lost its entity/art source evidence');
        for(const ref of binding.sourceRefs)if(ref.kind==='narration'&&!narration.segments.some(s=>s.id===ref.segmentId&&s.text.normalize('NFC').includes(ref.quote.normalize('NFC'))))return fail(slice,'model source quote is not in the original narration');
        validateManipulationActionSlices(owned.performance,owned.actions,slice.startMs);
        const actions=owned.actions.filter(a=>a.sourceManipulation?.sourceId===source.id&&a.sourceManipulation.gestureId===owned.gesture.id);
        if(actions.some(a=>a.target?.partId!==binding.partId||a.target.modelId!==slice.visualization!.modelId||a.target.anchor==='label'||rigHand(a)!==rigHand(owned.gesture)))return fail(slice,'original contact action targets a different sourced entity/hand');
        for(const action of actions){
          if(action.target!.anchor==='handle'&&!next.art?.handleAnchor)return fail(slice,'original transport handle requires its explicit authored artwork anchor');
          const anchor=partAnchor(slice,binding.partId,action.target!.anchor,p.stage.width,p.stage.height),grip={x:prop.origin.x+offset.x*p.scale,y:prop.origin.y+offset.y*p.scale};
          if(Math.hypot(anchor.x-grip.x,anchor.y-grip.y)>1e-6&&Math.hypot(Math.round(anchor.x*1000)/1000-grip.x,Math.round(anchor.y*1000)/1000-grip.y)>1e-6)return fail(slice,'authored center/handle differs from the original physical prop grip');
        }
        validateSourceGripWorld(slice,next.part,source.startMs+owned.gesture.contactMs!,source.startMs+(owned.gesture.releaseMs??owned.gesture.endMs),{startMs:source.startMs,endMs:source.endMs});
        const other=[...(slice.host?.actions??[]),...(slice.cinematic?.actorScene?.supporting.flatMap(a=>a.actions)??[])].filter(a=>[a.target,a.secondTarget].some(t=>t?.partId===binding.partId)&&!actions.includes(a));
        if(other.some(a=>a.endMs>source.startMs+owned.gesture.contactMs!))return fail(slice,'another fixed target/action cannot follow an original moving model');
        // The full source statement can be declared on the contact-owning slice;
        // later slices retain its real witness, never a new cue or contact.
        const evidence=slices.flatMap(s=>{const actor=propPerformer(s,(s.cinematic!.propBindings.find(b=>b.ownerId===sourceOwner.id&&b.propId===prop.id))!);return (s.cinematic?.sceneIntent?.acting??[]).some(a=>a.participantId===actor.id&&a.kind==='manipulation'&&a.operation===owned.gesture.action&&a.targetIds?.includes(binding.partId))?[s]:[];});
        let witnesses:ReturnType<typeof citedContact>=[];
        for(const s of evidence)witnesses.push(...citedContact(s,owned.id,owned.gesture,binding.partId,narration,source.startMs));
        if(!witnesses.length)return fail(slice,'original action lacks a complete narration witness in its source run');
        for(const action of actions){const cue=narration.segments.find(s=>s.id===action.narrationAnchor);
          if(!cue||!slice.narrationSegmentIds?.includes(cue.id)||cue.startMs>=action.endMs||cue.endMs<=action.startMs||!witnesses.some(w=>w.cueId===cue.id))return fail(slice,'camera action cue is not the original contact statement witness');}
      }
    }
  }
}
export const sourcePropBindingDescription={version:SOURCE_PROP_BINDING_VERSION,
  scope:'complete original story-person/model/entity/art/source/action/clock binding and physical entry/exit candidate',
  rule:'explicit binding ownerId on every source slice; stable canonical model origin/size/art/evidence and complete original narration witness; physical positions from actual original prop frame; explicit own authored handle matches actual original gripOffset; original person/model share one stage/floor and world cannot independently transform a physically bound entity',
  pending:['original world/event/interaction runtime and film acceptance','integrated source production audit and shared/sequential ownership','full runtime/art/motion/video/input/resume acceptance'],
  productionBinding:'needs-source-prop-binding',approved:false,productionReady:false,motionVerified:false};

import type {Shot,Storyboard,Narration} from '../core/schemas.js';
import {hash} from '../core/utils.js';
import {samplePhysicalPerformance,gestureRecoveryStart} from '../animation/compiler.js';
import {actorProfile} from '../actors/model.js';
import {actorViewActingClock} from '../actors/view-acting-clock.js';
import {sourceActor} from './source-actor.js';
import {boundProp,assertPropAliasCoverage} from './prop-owner.js';
import {validateSourceOwnershipTimelines,sourceOwnershipFrame,sourceOwnershipBoundary} from './source-ownership.js';
import {validateSourceWorld} from './source-world.js';
import {validateSourceGripWorld} from './source-grip-world.js';
import {OwnershipPaintSchema,type OwnershipPaint} from './ownership-paint-schemas.js';
import {bakeOwnership,type OwnershipBake} from './ownership-bake.js';
import type {SourceOwnership} from './source-ownership-schemas.js';
import {OWNERSHIP_RENDER_VERSION} from './ownership-render-version.js';
export {OWNERSHIP_RENDER_VERSION} from './ownership-render-version.js';

export interface CompiledOwnership {
  version:typeof OWNERSHIP_RENDER_VERSION;source:SourceOwnership;paint:OwnershipPaint;bake:OwnershipBake;
  aliases:Array<{actorId:string;propId:string;svgId:string;hand:'left'|'right';handSvgId:string;slotSvgId:string}>;
  shotHash:string;sourceHash:string;paintHash:string;motionVerified:false;productionApproval:false;
}
const fail=(shot:Shot,message:string):never=>{throw new Error(`${shot.id}: needs-source-prop-binding: ownership render ${message}`);};

/** Candidate compilation on canonical original source, not a production gate
 * override. Called only when a tester or future complete renderer requests it.
 * Current production entry still rejects unaccepted original ownership. */
export function compileSourceOwnership(shot:Shot,board:Storyboard,narration:Narration,actorBreakpoints:readonly number[]=[]):ReadonlyMap<string,CompiledOwnership>{
  if(!shot.cinematic?.sourceOwnership?.length)return fail(shot,'requires explicit original ownership');
  if(board.shots.filter(s=>s.id===shot.id).length!==1||hash(board.shots.find(s=>s.id===shot.id))!==hash(shot))return fail(shot,'requires the authoritative complete storyboard');
  // This is an immutable in-memory source snapshot for the synchronous bake.
  // No files, providers, approval flags or outside state are changed.
  const original=structuredClone(board),voice=structuredClone(narration),canonical=original.shots.find(s=>s.id===shot.id)!;
  validateSourceOwnershipTimelines(canonical,original,voice);
  validateSourceWorld(canonical,original,voice);
  const sources=canonical.cinematic!.sourceOwnership!,paints=canonical.cinematic!.ownershipPaint??[];
  if(paints.length!==sources.length||new Set(paints.map(p=>p.sourceId)).size!==paints.length)return fail(shot,'every entity requires one explicit depth plan');
  const allAliases=sources.flatMap(s=>s.grips.map(g=>JSON.stringify([g.actorId,g.propId])));
  if(new Set(allAliases).size!==allAliases.length)return fail(shot,'each original actor/prop alias must belong to one canonical entity');
  assertPropAliasCoverage(canonical);
  if(canonical.cinematic!.propBindings.length!==allAliases.length||canonical.cinematic!.propBindings.some(b=>!b.ownerId||!allAliases.includes(JSON.stringify([b.ownerId,b.propId]))))
    return fail(shot,'mixed unregistered/local prop rendering is not supported by this candidate; preserve and report the missing physical binding');
  const result=new Map<string,CompiledOwnership>();
  for(const source of sources){
    const matches=paints.filter(p=>p.sourceId===source.id);if(matches.length!==1)return fail(shot,'missing entity depth plan');
    const paint=OwnershipPaintSchema.parse(matches[0]),part=canonical.visualization!.parts.find(p=>p.id===source.partId)!;
    if(paint.grips.length!==source.grips.length||paint.grips.some(g=>!source.grips.some(s=>s.id===g.gripId)))return fail(shot,'depth plan must name every actual original grip exactly once');
    for(const painted of paint.grips){
      const grip=source.grips.find(g=>g.id===painted.gripId)!;
      const offset={x:(painted.anchor.x-.5)*part.width*canonical.cinematic!.performance.stage.width,y:(painted.anchor.y-.5)*part.height*canonical.cinematic!.performance.stage.height};
      if(Math.hypot(offset.x-grip.gripOffset.x,offset.y-grip.gripOffset.y)>1e-6)return fail(shot,'own authored viewport grip anchor differs from the actual stage grip offset');
      const actor=sourceActor(canonical,grip.actorId);
      if(actor.actions.filter(a=>a.sourceManipulation?.sourceId===grip.sourceId&&a.sourceManipulation.gestureId===grip.gestureId).some(a=>a.target?.anchor==='center'&&(painted.anchor.x!==.5||painted.anchor.y!==.5)))
        return fail(shot,'an off-center grip cannot claim a center action target');
    }
    if(paint.sourceRefs.some(ref=>!part.sourceRefs.some(r=>hash(r)===hash(ref))))return fail(shot,'depth plan lost canonical entity evidence');
    for(const slice of original.shots.filter(s=>s.startMs<source.endMs&&s.endMs>source.startMs))
      if(slice.cinematic?.ownershipPaint?.filter(p=>p.sourceId===source.id&&hash(p)===hash(paint)).length!==1)return fail(slice,'entity depth plan changed at a camera cut');
    for(const phase of source.phases.filter(p=>p.kind!=='world'))validateSourceGripWorld(canonical,part,phase.startMs,phase.endMs,{startMs:source.startMs,endMs:source.endMs});
    // Check every full-original transfer, even if this camera starts later.
    // Never smooth a source discontinuity or start a new contact at the cut.
    for(const transition of source.transitions)sourceOwnershipBoundary(canonical,source.id,transition.id,original,voice);
    const aliases=source.grips.map(grip=>{
      const binding=canonical.cinematic!.propBindings.find(b=>b.ownerId===grip.actorId&&b.propId===grip.propId&&b.partId===source.partId)!;
      const owned=boundProp(canonical,binding);
      return {actorId:grip.actorId,propId:grip.propId,svgId:owned.svgId,hand:grip.hand,handSvgId:`${owned.prefix}hand-${grip.hand}`,slotSvgId:`${owned.prefix}hand-${grip.hand}-prop-slot`};
    });
    const people=new Map(source.grips.map(g=>{
      const actor=sourceActor(canonical,g.actorId),clock=actorViewActingClock(original,canonical,g.actorId);
      if(!clock?.manipulationMotion)return fail(shot,'missing actual original person clock');
      return [g.actorId,{actor,profile:actorProfile(actor.character),clock}] as const;
    }));
    const resolve=(global:number)=>{
      const frame=sourceOwnershipFrame(canonical,source.id,global,original,voice),frames=new Map<string,ReturnType<typeof samplePhysicalPerformance>>();
      const palms=Object.fromEntries(source.grips.map(g=>{
        let body=frames.get(g.actorId);
        if(!body){const owned=people.get(g.actorId)!;body=samplePhysicalPerformance(owned.actor.performance,owned.profile,global-canonical.startMs,owned.clock);frames.set(g.actorId,body);}
        return [g.id,body.hands[g.hand]] as const;
      }));
      return {timeMs:global,center:frame.center,palms,activeGripIds:frame.grips.map(g=>g.gripId),...(frame.authorityGripId===undefined?{}:{authorityGripId:frame.authorityGripId})};
    };
    // Observation queries (contact and action entry) must be mandatory samples
    // even when a diagnostic has no rendered actor compiler to supply frames.
    const semanticTimes=[...people.values()].flatMap(({actor})=>{
      const original=actor.performance.sourceManipulation!;
      return original.gestures.flatMap(g=>[g.startMs,g.contactMs,g.releaseMs,g.landingMs,g.endMs,gestureRecoveryStart(g)].filter((at):at is number=>at!==undefined).map(at=>original.startMs+at));
    }).filter(at=>at>=source.startMs&&at<=source.endMs);
    const bake=bakeOwnership(source,canonical.startMs,canonical.endMs,canonical.cinematic!.performance.fps,[...actorBreakpoints,...semanticTimes],resolve);
    result.set(source.partId,{version:OWNERSHIP_RENDER_VERSION,source,paint,bake,aliases,shotHash:hash(canonical),sourceHash:hash({source,original,voice}),paintHash:hash(paint),motionVerified:false,productionApproval:false});
  }
  return result;
}

export const ownershipRenderDescription={version:OWNERSHIP_RENDER_VERSION,status:'candidate',
  geometry:'single entity from original ownership; shared palms agree, boundaries checked before interpolation; own original actor compiler breakpoints and a common original fps clock',
  paint:'explicit ownershipPaint for each entity and own original grip; own authored normalized viewport grip anchor matches physical stage offset; entity behind/in front of actors, each palm before/after entity; no inference from left/right, near/far or camera primary',
  interpolation:'measured sampled spatial error <=0.2px at interval probes; discrete grip/authority never tween; bounded refinement fails closed; renderer and relations consume fresh validated bake snapshots, same checks as observations',
  pending:['actual source geometry/bake/SVG/runtime and film acceptance','source observation integration runtime, publication/review/QC and complete production audit','rotating tools/airborne drops and full faithful art/motion/input/voice/resume/final acceptance'],
  productionBinding:'needs-source-prop-binding',approved:false,productionReady:false,motionVerified:false,productionApproval:false};

import type {Shot} from '../core/schemas.js';
import type {CinematicPlan} from './schemas.js';
import {performanceProps} from '../animation/view-source-manipulation.js';

/** Actor-local prop names are not identities across a visible cast. */
export const propAliasIdentity=(ownerId:string,propId:string)=>JSON.stringify([ownerId,propId]);

/** Ownership is a story-person ID, independent of lead role, model or rig identity.
 * Omission retains the original primary/presenter contract; never infer a
 * supporting owner from a prop name or whichever gesture happens to match. */
export function propPerformer(shot:Shot,binding:CinematicPlan['propBindings'][number]){
  const c=shot.cinematic;if(!c)throw new Error(`${shot.id}: bound prop requires cinematic data`);
  const id=binding.ownerId??c.actorScene?.primary?.id??c.leadCharacterId;
  if(c.actorScene&&[...(c.actorScene.primary?[c.actorScene.primary.id]:[]),...c.actorScene.supporting.map(a=>a.character.id)].filter(actorId=>actorId===id).length!==1)throw new Error(`${shot.id}: prop ${binding.propId} owner ${id} is not one visible story actor`);
  if(c.actorScene?.primary?.id===id||!c.actorScene&&id===c.leadCharacterId){
    return {id,performance:c.performance,actions:shot.host?.actions??[],prefix:'',character:c.actorScene?.primary??undefined};
  }
  if(binding.ownerId===undefined)throw new Error(`${shot.id}: bound prop has no primary owner; supporting ownership must be explicit`);
  const matches=c.actorScene?.supporting.filter(a=>a.character.id===id)??[];
  if(matches.length!==1)throw new Error(`${shot.id}: prop ${binding.propId} owner ${id} is not one visible story actor`);
  const actor=matches[0]!;
  return {id,performance:actor.performance,actions:actor.actions,prefix:`actor-${id}-`,character:actor.character};
}

export function boundProp(shot:Shot,binding:CinematicPlan['propBindings'][number]){
  const owner=propPerformer(shot,binding),prop=performanceProps(owner.performance).find(p=>p.id===binding.propId);
  if(!prop)throw new Error(`${shot.id}: prop ${binding.propId} is missing from its explicit owner ${owner.id}`);
  return {...owner,prop,svgId:`${owner.prefix}prop-${binding.propId}`};
}

/** Bind every actual person's prop once, without overwriting another person's
 * same local name. Generated SVG namespace collisions still reject. */
export function assertPropAliasCoverage(shot:Shot):void {
  const c=shot.cinematic;if(!c)return;
  const primary=c.actorScene?c.actorScene.primary?.id:c.leadCharacterId;
  const declaredPrimary=performanceProps(c.performance);
  if(!primary&&declaredPrimary.length)throw new Error(`${shot.id}: prop has no visible primary owner`);
  const declared=[...declaredPrimary.map(prop=>propAliasIdentity(primary!,prop.id)),
    ...(c.actorScene?.supporting.flatMap(actor=>performanceProps(actor.performance).map(prop=>propAliasIdentity(actor.character.id,prop.id)))??[])];
  if(new Set(declared).size!==declared.length)throw new Error(`${shot.id}: prop IDs must be unique within each actual actor`);
  const aliases=c.propBindings.map(binding=>{const owner=boundProp(shot,binding);return {identity:propAliasIdentity(owner.id,binding.propId),svgId:owner.svgId};});
  if(aliases.length!==declared.length||new Set(aliases.map(a=>a.identity)).size!==aliases.length||aliases.some(a=>!declared.includes(a.identity)))
    throw new Error(`${shot.id}: every animated actor/prop alias requires exactly one sourced model binding`);
  if(new Set(aliases.map(a=>a.svgId)).size!==aliases.length)throw new Error(`${shot.id}: bound prop namespaces collide; use unambiguous actor/prop IDs`);
}

import type {FrameState} from '../animation/compiler.js';

/** Shared scene channels name canonical entities, never actor-local prop IDs. */
export interface ModelMotionFrame {timeMs:number;centers:Record<string,{x:number;y:number}>;}
export type CompiledPropFrame=Pick<FrameState,'timeMs'|'props'>;
export interface CompiledModelSource {partId:string;ownerId:string;propId:string;frames:readonly CompiledPropFrame[];}

export function validateModelMotionFrames(frames:readonly ModelMotionFrame[],partIds:readonly string[],durationMs:number):void {
  const ids=[...new Set(partIds)];
  if(!Number.isFinite(durationMs)||durationMs<=0||!frames.length||frames[0]!.timeMs!==0||frames.at(-1)!.timeMs!==durationMs)throw new Error('Model motion needs the complete canonical shot clock');
  let previous=-1;
  for(const frame of frames){
    if(!Number.isFinite(frame.timeMs)||frame.timeMs<=previous)throw new Error('Model motion has an invalid canonical entity clock');
    previous=frame.timeMs;
    if(Object.keys(frame.centers).length!==ids.length||ids.some(id=>!Object.hasOwn(frame.centers,id)||![frame.centers[id]!.x,frame.centers[id]!.y].every(Number.isFinite)))
      throw new Error('Model motion lacks exactly the bound canonical entity centers');
  }
}

/** Union of real owners' adaptive keyframes. Read precisely the piecewise-linear
 * centers drawn by those owners; do not resample bones, faces or physics. An
 * explicit entity key prevents two people's same local name overwriting one
 * another. Shared ownership supplies its separate single canonical bake. */
export function compiledModelFrames(base:readonly CompiledPropFrame[],sources:readonly CompiledModelSource[]):ModelMotionFrame[]{
  const clock=(frames:readonly CompiledPropFrame[],end?:number)=>{
    if(!frames.length||frames[0]!.timeMs!==0||end!==undefined&&frames.at(-1)!.timeMs!==end)throw new Error('Model motion has a different compiled scene clock');
    let previous=-1;
    for(const frame of frames){if(!Number.isFinite(frame.timeMs)||frame.timeMs<=previous)throw new Error('Model motion has an invalid compiled clock');previous=frame.timeMs;}
    if(previous<=0)throw new Error('Model motion needs a positive complete shot clock');
    return previous;
  };
  const end=clock(base),times=new Set(base.map(f=>f.timeMs)),entities=new Set<string>();
  for(const source of sources){
    if(!source.partId||!source.ownerId||!source.propId||entities.has(source.partId))throw new Error('Model motion needs exactly one actual owner source per canonical entity');
    entities.add(source.partId);clock(source.frames,end);
    for(const frame of source.frames){
      const prop=Object.hasOwn(frame.props,source.propId)?frame.props[source.propId]:undefined;
      if(!prop||![prop.point.x,prop.point.y].every(Number.isFinite))throw new Error(`Model ${source.partId} owner ${source.ownerId} has missing or invalid compiled prop centers`);
      times.add(frame.timeMs);
    }
  }
  const bracket=(frames:readonly CompiledPropFrame[],time:number)=>{
    let low=0,high=frames.length-1;
    while(low<high){const middle=Math.floor((low+high)/2);if(frames[middle]!.timeMs<time)low=middle+1;else high=middle;}
    const right=frames[low]!,left=frames[Math.max(0,low-1)]!;
    return {left,right,weight:left.timeMs===right.timeMs?0:(time-left.timeMs)/(right.timeMs-left.timeMs)};
  };
  return [...times].sort((a,b)=>a-b).map(timeMs=>{
    const centers:ModelMotionFrame['centers']=Object.create(null);
    for(const source of sources){
      const {left,right,weight}=bracket(source.frames,timeMs),a=left.props[source.propId]!.point,b=right.props[source.propId]!.point;
      const point={x:a.x+(b.x-a.x)*weight,y:a.y+(b.y-a.y)*weight};
      if(![point.x,point.y].every(Number.isFinite))throw new Error(`Model ${source.partId} has invalid interpolated centers`);
      centers[source.partId]=point;
    }
    return {timeMs,centers};
  });
}

