      result.calls.push(`tl.${previous?'to':'set'}(${JSON.stringify(selector(shot,'object-'+index,' .bound-model-shadow'))},${JSON.stringify({...delta,attr:{transform:`translate(0 ${y-sample.center.y})`}})},${at});`);
